341	     * the tax rate: first what it still owes, then the retention it holds back. The part taken off in
342	     * all, and of that the part clearing retention; the rest is left over as credit.
343	     */
344	    public BigDecimal[] creditTaken(BigDecimal amount, BigDecimal paid, BigDecimal taxRate) {
345	        BigDecimal toDue = amount.min(amountDue(paid, taxRate).max(BigDecimal.ZERO));
346	        BigDecimal toRetention = amount.subtract(toDue).min(retentionHeld(taxRate));
347	        return new BigDecimal[] { toDue.add(toRetention), toRetention };
