385	    /**
386	     * The plan's schedule at the tax rate, an ordinary loan of the grand total; empty when there is no
387	     * plan. With the monthly rate i (the annual rate / 12 / 100) the instalment is P x i / (1 - (1 +
388	     * i)^-n), or P / n at 0%, rounded half up to the cent. Each month's interest is the balance still
389	     * owed x i, rounded half up to the cent, and its principal the instalment less the interest; the
390	     * last instalment pays off the whole balance left plus its interest, so the schedule ends at zero.
391	     * Instalment k falls due k months after the issue date, on the same day (the month's last day when
392	     * it is shorter).
393	     */
394	    public List<Instalment> schedule(BigDecimal taxRate) {
395	        if (!hasPlan()) {
396	            return List.of();
397	        }
398	        MathContext mc = MathContext.DECIMAL128;
399	        BigDecimal principal = total(taxRate);
400	        BigDecimal i = instalmentRate.divide(BigDecimal.valueOf(1200), mc);
401	        int n = instalments;
402	        BigDecimal payment;
403	        if (i.signum() == 0) {
404	            payment = principal.divide(BigDecimal.valueOf(n), 2, RoundingMode.HALF_UP);
405	        } else {
406	            BigDecimal growth = BigDecimal.ONE.add(i).pow(n, mc);
407	            payment = principal.multiply(i).multiply(growth)
408	                    .divide(growth.subtract(BigDecimal.ONE), mc).setScale(2, RoundingMode.HALF_UP);
409	        }
410	        List<Instalment> schedule = new ArrayList<>(n);
411	        BigDecimal balance = principal.setScale(2, RoundingMode.HALF_UP);
412	        for (int k = 1; k <= n; k++) {
413	            BigDecimal interest = balance.multiply(i).setScale(2, RoundingMode.HALF_UP);
414	            BigDecimal paid = k == n ? balance.add(interest) : payment;
415	            BigDecimal repaid = paid.subtract(interest);
416	            balance = balance.subtract(repaid);
417	            LocalDate due = issueDate == null ? null : issueDate.plusMonths(k);
418	            schedule.add(new Instalment(k, due, paid, interest, repaid, balance));
419	        }
420	        return schedule;
421	    }
