423	    /** The plan total at the tax rate: the sum of the instalments; null when there is no plan. */
424	    public BigDecimal planTotal(BigDecimal taxRate) {
425	        if (!hasPlan()) {
426	            return null;
427	        }
428	        return schedule(taxRate).stream().map(Instalment::payment).reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
429	    }
