431	    /**
432	     * Each instalment of the plan at the tax rate once the given amount has been paid, on the given
433	     * day: payments (with what credit notes took off and anything written off) pay the instalments in
434	     * order, each paid off before the next. An instalment not paid off more than {@link #GRACE_DAYS}
435	     * days after its due date is overdue; empty when there is no plan.
436	     */
437	    public List<Instalment.Progress> instalmentProgress(BigDecimal paid, BigDecimal taxRate, LocalDate today) {
438	        List<Instalment.Progress> progress = new ArrayList<>();
439	        BigDecimal left = paid.add(getCredited()).add(writtenOff(paid, taxRate));
440	        for (Instalment instalment : schedule(taxRate)) {
441	            BigDecimal part = left.min(instalment.payment()).max(BigDecimal.ZERO).setScale(2, RoundingMode.HALF_UP);
442	            left = left.subtract(part);
443	            BigDecimal unpaid = instalment.payment().subtract(part);
444	            Instalment.Status status;
445	            if (unpaid.signum() <= 0) {
446	                status = Instalment.Status.PAID;
447	            } else if (instalment.dueDate() != null && today.isAfter(instalment.dueDate().plusDays(GRACE_DAYS))) {
448	                status = Instalment.Status.OVERDUE;
449	            } else if (part.signum() > 0) {
450	                status = Instalment.Status.PART_PAID;
451	            } else {
452	                status = Instalment.Status.DUE;
453	            }
454	            progress.add(new Instalment.Progress(instalment, part, unpaid, status));
455	        }
456	        return progress;
457	    }
