459	    /**
460	     * What is overdue at the tax rate once the given amount has been paid, on the given day: for a plan,
461	     * only what is unpaid on its overdue instalments; otherwise all that is due when it is overdue.
462	     */
463	    public BigDecimal overdueAmount(BigDecimal paid, BigDecimal taxRate, LocalDate today) {
464	        if (statusWhenPaid(paid, taxRate, today) != InvoiceStatus.OVERDUE) {
465	            return BigDecimal.ZERO.setScale(2);
466	        }
467	        if (!hasPlan()) {
468	            return amountDue(paid, taxRate);
469	        }
470	        return instalmentProgress(paid, taxRate, today).stream()
471	                .filter(p -> p.status() == Instalment.Status.OVERDUE).map(Instalment.Progress::unpaid)
472	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
473	    }
