561	    /** Days past its due date an invoice is given before it becomes overdue: a week's grace. */
562	    public static final int GRACE_DAYS = 7;
563	
564	    /**
565	     * The status on the given day once the given amount has been paid against the grand total at the
566	     * tax rate: a sent invoice with something still due more than {@link #GRACE_DAYS} days after its
567	     * due date is overdue, part paid or not. Held retention is never due, so never makes it overdue;
568	     * released retention is due {@link #RETENTION_DUE_DAYS} days after its release, and payments go to
569	     * the rest of the invoice before it. An invoice spread over instalments is instead overdue when any
570	     * of its instalments is (see {@link #instalmentProgress}).
571	     */
572	    public InvoiceStatus statusWhenPaid(BigDecimal paid, BigDecimal taxRate, LocalDate today) {
573	        return statusWhenPaid(paid, null, taxRate, today);
574	    }
575	
576	    /**
577	     * As {@link #statusWhenPaid(BigDecimal, BigDecimal, LocalDate)}, but a fully paid invoice whose
578	     * paid date (null when not known) is after its due date is paid late.
579	     */
580	    public InvoiceStatus statusWhenPaid(BigDecimal paid, LocalDate paidOn, BigDecimal taxRate, LocalDate today) {
581	        if (status != InvoiceStatus.SENT) {
582	            return status;
583	        }
584	        BigDecimal amountDue = amountDue(paid, taxRate);
585	        boolean due = amountDue.signum() > 0;
586	        BigDecimal retentionDue = amountDue.min(retentionReleased(taxRate)).max(BigDecimal.ZERO);
587	        boolean restDue = amountDue.subtract(retentionDue).signum() > 0;
588	        if (hasPlan()) {
589	            if (due && instalmentProgress(paid, taxRate, today).stream()
590	                    .anyMatch(p -> p.status() == Instalment.Status.OVERDUE)) {
591	                return InvoiceStatus.OVERDUE;
592	            }
593	        } else if (restDue && dueDate != null && today.isAfter(dueDate.plusDays(GRACE_DAYS))) {
594	            return InvoiceStatus.OVERDUE;
595	        }
596	        if (retentionDue.signum() > 0 && today.isAfter(retentionDueDate().plusDays(GRACE_DAYS))) {
597	            return InvoiceStatus.OVERDUE;
598	        }
599	        if (!due && retentionHeld(taxRate).signum() > 0) {
600	            return InvoiceStatus.RETENTION_HELD;
601	        }
602	        if (paid.signum() <= 0) {
603	            return !due && getCredited().signum() > 0 ? InvoiceStatus.CREDITED : status;
604	        }
605	        if (due) {
606	            return InvoiceStatus.PART_PAID;
607	        }
608	        return paidOn != null && dueDate != null && paidOn.isAfter(dueDate) ? InvoiceStatus.PAID_LATE
609	                : InvoiceStatus.PAID;
610	    }
611	
612	    /**
613	     * The date the invoice was fully paid: the date of the payment that cleared its grand total at the
614	     * tax rate, taking the parts of payments (not reversed) in the order they were applied (credit used
615	     * counts on the day it was applied); null while something is still due or retention is held.
616	     */
617	    public LocalDate paidOn(List<Payment> payments, BigDecimal taxRate) {
618	        BigDecimal total = payable(taxRate);
619	        if (status != InvoiceStatus.SENT || total.signum() <= 0 || retentionHeld(taxRate).signum() > 0) {
620	            return null;
621	        }
622	        record Part(LocalDate on, Long paymentId, BigDecimal amount) {
623	        }
624	        List<Part> inOrder = payments.stream().filter(p -> !p.isReversed())
625	                .flatMap(p -> p.getAllocations().stream().filter(a -> a.getInvoiceId().equals(id))
626	                        .map(a -> new Part(a.getDate() == null ? p.getDate() : a.getDate(), p.getId(), a.getAmount())))
627	                .sorted(Comparator.comparing(Part::on).thenComparing(Part::paymentId)).toList();
628	        BigDecimal sum = BigDecimal.ZERO;
629	        for (Part p : inOrder) {
630	            sum = sum.add(p.amount());
631	            if (sum.signum() > 0 && total.subtract(sum).compareTo(WRITE_OFF_LIMIT) < 0) {
632	                return p.on();
633	            }
634	        }
635	        return null;
636	    }
637	
638	    /**
639	     * What is still due once the given amount has been paid: the grand total less it, less what credit
640	     * notes have credited, less the retention still held, less anything written off — so nothing once
641	     * payments leave less than {@link #WRITE_OFF_LIMIT}. A credit note itself has nothing due.
642	     */
643	    public BigDecimal amountDue(BigDecimal paid, BigDecimal taxRate) {
644	        if (isCreditNote()) {
645	            return BigDecimal.ZERO.setScale(2);
646	        }
647	        return payable(taxRate).subtract(paid).subtract(writtenOff(paid, taxRate));
648	    }
649	
650	    /**
651	     * What is written off once the given amount has been paid: when payments leave less than
652	     * {@link #WRITE_OFF_LIMIT} still due, all of what is left; otherwise nothing.
653	     */
654	    public BigDecimal writtenOff(BigDecimal paid, BigDecimal taxRate) {
655	        BigDecimal left = payable(taxRate).subtract(paid);
656	        return !isCreditNote() && paid.signum() > 0 && left.signum() > 0 && left.compareTo(WRITE_OFF_LIMIT) < 0
657	                ? left.setScale(2, RoundingMode.HALF_UP)
658	                : BigDecimal.ZERO.setScale(2);
659	    }
660	
661	    /** The least a part payment may be at the tax rate: {@link #MINIMUM_PART_SHARE} of the grand total. */
662	    public BigDecimal minimumPart(BigDecimal taxRate) {
663	        return total(taxRate).multiply(MINIMUM_PART_SHARE).setScale(2, RoundingMode.HALF_UP);
664	    }
665	
666	    /**
667	     * Whether paying the amount on top of what was already paid is too small a part payment: under
668	     * {@link #minimumPart} while leaving something still due (what would be written off counts as settled).
669	     * For a plan the least is instead what is still unpaid on its earliest unpaid instalment.
670	     */
671	    public boolean isTooSmallPart(BigDecimal amount, BigDecimal paid, BigDecimal taxRate) {
672	        if (hasPlan()) {
673	            return amount.compareTo(earliestUnpaid(paid, taxRate)) < 0
674	                    && amountDue(paid.add(amount), taxRate).signum() > 0;
675	        }
676	        return amount.compareTo(minimumPart(taxRate)) < 0 && amountDue(paid.add(amount), taxRate).signum() > 0;
677	    }
