708	    /**
709	     * Changes the line with the given id to the given values; whether the invoice had it. Refused when
710	     * the subtotal would then be less than a fixed discount on the invoice.
711	     */
712	    public boolean updateLine(Long lineId, String description, BigDecimal qty, BigDecimal unitPrice,
713	            boolean taxExempt, BigDecimal discountPct, BigDecimal taxRate) {
714	        InvoiceLine line = lines.stream().filter(l -> lineId.equals(l.getId())).findFirst().orElse(null);
715	        if (line == null) {
716	            return false;
717	        }
718	        BigDecimal changed = new InvoiceLine(description, qty, unitPrice, taxExempt, discountPct, taxRate).amount();
719	        BigDecimal left = subtotal().subtract(line.amount()).add(changed);
720	        if (discountAmount.signum() > 0 && left.compareTo(discountAmount) < 0) {
721	            throw new InvoiceRejectedException("This line cannot be changed: the $"
722	                    + left.setScale(2).toPlainString() + " subtotal would be less than the $"
723	                    + discountAmount.setScale(2).toPlainString() + " discount.");
724	        }
725	        line.update(description, qty, unitPrice, taxExempt, discountPct, taxRate);
726	        return true;
727	    }
