729	    /**
730	     * The sum of the line amounts, each after its own discount and already to the cent — so the subtotal
731	     * matches what a client gets by adding up the lines shown.
732	     */
733	    public BigDecimal subtotal() {
734	        return lines.stream().map(InvoiceLine::amount)
735	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
736	    }
737	
738	    /**
739	     * The amount taken off: the fixed amount when there is one (never more than the subtotal, should
740	     * lines have been changed since), otherwise the discount percentage of the subtotal, rounded down
741	     * to the cent. When there is a cap, it limits everything taken off — the line discounts plus
742	     * this — so this shrinks to what the line discounts leave under the cap, never below zero.
743	     */
744	    public BigDecimal discount() {
745	        BigDecimal discount = discountAmount.signum() > 0
746	                ? discountAmount.min(subtotal()).setScale(2, RoundingMode.HALF_UP)
747	                : subtotal().multiply(discountPct).divide(BigDecimal.valueOf(100)).setScale(2, RoundingMode.DOWN);
748	        if (discountCap == null) {
749	            return discount;
750	        }
751	        BigDecimal lineDiscounts = lines.stream().map(InvoiceLine::discount)
752	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
753	        BigDecimal left = discountCap.setScale(2, RoundingMode.HALF_UP).subtract(lineDiscounts).max(BigDecimal.ZERO.setScale(2));
754	        return discount.min(left);
755	    }
756	
757	    /**
758	     * Each line's share of the discount, in the order of the lines. The discount's cents are split in
759	     * proportion to the line amounts: each line first gets the whole cents of its exact share
760	     * (rounded down), then the cents left over go one each to the lines with the largest leftover
761	     * fractions; between equal fractions the cent goes to the line with the larger amount, and between
762	     * equal amounts too to the lower line id. The shares add up to the discount.
763	     */
764	    public List<BigDecimal> discountShares() {
765	        BigInteger discountCents = discount().movePointRight(2).toBigIntegerExact();
766	        BigInteger subtotalCents = subtotal().movePointRight(2).toBigIntegerExact();
767	        int n = lines.size();
768	        BigInteger[] shares = new BigInteger[n];
769	        BigInteger[] leftovers = new BigInteger[n];
770	        BigInteger given = BigInteger.ZERO;
771	        for (int i = 0; i < n; i++) {
772	            if (subtotalCents.signum() == 0) {
773	                shares[i] = BigInteger.ZERO;
774	                leftovers[i] = BigInteger.ZERO;
775	            } else {
776	                // The exact share is discount * amount / subtotal; all fractions share the subtotal
777	                // as denominator, so the remainders compare as the fractions do.
778	                BigInteger[] qr = discountCents.multiply(lines.get(i).amount().movePointRight(2).toBigIntegerExact())
779	                        .divideAndRemainder(subtotalCents);
780	                shares[i] = qr[0];
781	                leftovers[i] = qr[1];
782	            }
783	            given = given.add(shares[i]);
784	        }
785	        List<Integer> order = new ArrayList<>();
786	        for (int i = 0; i < n; i++) {
787	            order.add(i);
788	        }
789	        order.sort(Comparator.<Integer, BigInteger>comparing(i -> leftovers[i]).reversed()
790	                .thenComparing(Comparator.<Integer, BigDecimal>comparing(i -> lines.get(i).amount()).reversed())
791	                .thenComparing(i -> lines.get(i).getId(), Comparator.nullsLast(Comparator.naturalOrder())));
792	        int left = discountCents.subtract(given).intValueExact();
793	        for (int k = 0; k < left; k++) {
794	            int i = order.get(k);
795	            shares[i] = shares[i].add(BigInteger.ONE);
796	        }
797	        List<BigDecimal> result = new ArrayList<>(n);
798	        for (BigInteger share : shares) {
799	            result.add(new BigDecimal(share, 2));
800	        }
801	        return result;
802	    }
803	
804	    /**
805	     * Each line's tax, in the order of the lines: the line's own rate (a percentage), or the given
806	     * workspace rate when it has none, on the line's amount less its share of the discount, rounded
807	     * half up to the cent. Tax-exempt lines, and every line of a tax-exempt client, have no tax.
808	     */
809	    public List<BigDecimal> lineTaxes(BigDecimal taxRate) {
810	        List<BigDecimal> shares = discountShares();
811	        List<BigDecimal> taxes = new ArrayList<>(lines.size());
812	        for (int i = 0; i < lines.size(); i++) {
813	            InvoiceLine line = lines.get(i);
814	            taxes.add(clientTaxExempt || line.isTaxExempt() ? BigDecimal.ZERO.setScale(2)
815	                    : line.amount().subtract(shares.get(i)).multiply(line.taxRate(taxRate)).divide(BigDecimal.valueOf(100))
816	                            .setScale(2, RoundingMode.HALF_UP));
817	        }
818	        return taxes;
819	    }
820	
821	    /** The tax charged at the given rate (a percentage): the sum of the line taxes. */
822	    public BigDecimal tax(BigDecimal taxRate) {
823	        return lineTaxes(taxRate).stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
824	    }
825	
826	    /** The grand total: the subtotal less the discount, plus tax at the given rate. */
827	    public BigDecimal total(BigDecimal taxRate) {
828	        return subtotal().subtract(discount()).add(tax(taxRate));
829	    }
830	}
