429	     * Issues the draft credit note today and records it in the audit: its grand total comes off what
430	     * its original still owes, then the retention it holds back; any rest is held on the client's
431	     * account as a credit payment dated today, also recorded in the audit.
432	     */
433	    private void issue(Invoice note) {
434	        BigDecimal rate = taxRate.percent();
435	        Invoice original = invoices.findWithLinesById(note.getCreditOf()).orElseThrow();
436	        // Read again what it has been credited: another credit note may just have been issued against it.
437	        entityManager.refresh(original);
438	        BigDecimal total = note.total(rate);
439	        BigDecimal[] taken = original.creditTaken(total, paid(List.of(original)).get(original.getId()), rate);
440	        note.markIssued(today.date(), rate, taken[0], taken[1]);
441	        invoices.saveAndFlush(note);
442	        audit.record("CREDIT_NOTE_ISSUED id=" + note.getId() + " number=" + note.number() + " invoice="
443	                + note.getCreditOf() + " total=" + total.toPlainString());
444	        BigDecimal rest = total.subtract(taken[0]);
445	        if (rest.signum() > 0) {
446	            recordCreditHeld(payments.saveAndFlush(Payment.fromCreditNote(note, rest)));
447	        }
