468	     * credit first (lower id first on the same date), each part applied today and recorded in the audit.
469	     */
470	    private void applyCredit(Invoice invoice) {
471	        BigDecimal due = invoice.amountDue(paid(List.of(invoice)).get(invoice.getId()), taxRate.percent());
472	        LocalDate now = today.date();
473	        boolean used = false;
474	        for (Payment payment : payments.findForClient(invoice.getClientId())) {
475	            if (due.signum() <= 0) {
476	                break;
477	            }
478	            BigDecimal credit = payment.credit();
479	            if (credit.signum() <= 0) {
480	                continue;
481	            }
482	            BigDecimal part = credit.min(due);
483	            payment.apply(invoice.getId(), part, now);
484	            payments.saveAndFlush(payment);
485	            audit.record("PAYMENT_RECORDED id=" + payment.getId() + " invoice=" + invoice.getId() + " amount="
486	                    + part.setScale(2, RoundingMode.UNNECESSARY).toPlainString());
487	            due = due.subtract(part);
488	            used = true;
489	        }
490	        if (used) {
