503	            return Optional.empty();
504	        }
505	        LocalDate now = today.date();
506	        if (date.isAfter(now)) {
507	            throw new InvoiceRejectedException("The payment date cannot be after today (" + now + ").");
508	        }
509	        Payment payment = payments.saveAndFlush(Payment.deposit(clientId, amount, date));
510	        audit.record("DEPOSIT_RECORDED id=" + payment.getId() + " client=" + clientId + " amount="
511	                + amount.setScale(2, RoundingMode.UNNECESSARY).toPlainString());
512	        return Optional.of(payment);
513	    }
514	
515	    /**
516	     * Refunds the amount of the client's unused credit on the date: the oldest payment's credit first
517	     * (lower id first on the same date), then the next, each part recorded in the audit; empty if no
518	     * such client. The amount has already been checked; a date after today or before a payment it
519	     * would come from, or an amount more than the client's credit, is refused.
520	     */
521	    @Transactional
522	    public Optional<Long> refundCredit(Long clientId, BigDecimal amount, LocalDate date) {
523	        if (clients.findById(clientId).isEmpty()) {
524	            return Optional.empty();
525	        }
526	        LocalDate now = today.date();
527	        if (date.isAfter(now)) {
528	            throw new InvoiceRejectedException("The refund date cannot be after today (" + now + ").");
529	        }
530	        List<Payment> from = new ArrayList<>();
531	        List<BigDecimal> parts = new ArrayList<>();
532	        BigDecimal left = amount;
533	        BigDecimal credit = BigDecimal.ZERO;
534	        for (Payment payment : payments.findForClient(clientId)) {
535	            BigDecimal unused = payment.credit();
536	            if (unused.signum() <= 0) {
537	                continue;
538	            }
539	            credit = credit.add(unused);
540	            if (left.signum() <= 0) {
541	                continue;
542	            }
543	            BigDecimal part = unused.min(left);
544	            if (date.isBefore(payment.getDate())) {
545	                throw new InvoiceRejectedException("The refund cannot be dated before the payment of "
546	                        + payment.getDate() + " it would come from.");
547	            }
548	            from.add(payment);
549	            parts.add(part);
550	            left = left.subtract(part);
551	        }
552	        if (left.signum() > 0) {
553	            throw new InvoiceRejectedException("The refund cannot be more than the client's unused credit of $"
554	                    + credit.setScale(2, RoundingMode.UNNECESSARY).toPlainString() + ".");
555	        }
556	        for (int i = 0; i < from.size(); i++) {
557	            Payment payment = from.get(i);
558	            payment.refund(parts.get(i));
559	            payments.saveAndFlush(payment);
560	            audit.record("CREDIT_REFUNDED payment=" + payment.getId() + " amount="
561	                    + parts.get(i).setScale(2, RoundingMode.UNNECESSARY).toPlainString());
562	        }
563	        return Optional.of(clientId);
564	    }
565	
566	    /** The unused credit of each client that has any, by client id. */
567	    @Transactional(readOnly = true)
568	    public Map<Long, BigDecimal> credits() {
569	        Map<Long, BigDecimal> credits = new HashMap<>();
570	        for (Payment payment : payments.findNotReversed()) {
571	            BigDecimal credit = payment.credit();
572	            if (credit.signum() > 0) {
573	                credits.merge(payment.getClientId(), credit, BigDecimal::add);
574	            }
575	        }
576	        return credits;
577	    }
578	
579	    /**
580	     * Voids a sent invoice with no payments, and records it in the audit; empty if no such invoice. A
581	     * draft, an invoice already void, or one with any payment is refused.
582	     */
583	    @Transactional
584	    public Optional<Invoice> voidInvoice(Long invoiceId) {
585	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
586	        found.ifPresent(invoice -> {
587	            if (invoice.isVoid()) {
588	                throw new InvoiceRejectedException("This invoice is already void.");
589	            }
590	            if (invoice.isDraft()) {
591	                throw new InvoiceRejectedException("A draft cannot be voided; only a sent invoice can.");
592	            }
593	            if (invoice.isCreditNote()) {
594	                throw new InvoiceRejectedException("An issued credit note cannot be voided.");
595	            }
596	            if (invoice.hasCreditNotesIssued()) {
597	                throw new InvoiceRejectedException("An invoice with an issued credit note cannot be voided.");
598	            }
599	            if (!payments.findForInvoice(invoice.getId()).isEmpty()) {
600	                throw new InvoiceRejectedException("An invoice with payments cannot be voided.");
601	            }
602	            invoice.markVoid();
603	            invoices.saveAndFlush(invoice);
604	            audit.record("INVOICE_VOIDED id=" + invoice.getId() + " number=" + invoice.number());
605	        });
606	        return found;
607	    }
608	
609	    /** The payments made to the invoice, oldest first, with their allocations. */
610	    @Transactional(readOnly = true)
611	    public List<Payment> payments(Long invoiceId) {
612	        return payments.findForInvoice(invoiceId);
613	    }
614	
615	    /** The date each fully paid invoice was paid (see {@link Invoice#paidOn}); an invoice not fully paid is left out. */
616	    @Transactional(readOnly = true)
617	    public Map<Long, LocalDate> paidOn(List<Invoice> list) {
618	        Map<Long, LocalDate> paidOn = new HashMap<>();
619	        if (list.isEmpty()) {
620	            return paidOn;
621	        }
622	        List<Payment> found = payments.findForInvoices(list.stream().map(Invoice::getId).toList());
623	        BigDecimal rate = taxRate.percent();
624	        for (Invoice i : list) {
625	            LocalDate on = i.paidOn(found, rate);
626	            if (on != null) {
627	                paidOn.put(i.getId(), on);
628	            }
629	        }
630	        return paidOn;
631	    }
