646	    /**
647	     * Records a payment of the amount on the date against a sent invoice that still has something
648	     * due, and records it in the audit; empty if no such invoice. The amount has already been
649	     * checked; what it pays beyond what is due is held on the client's account as credit. A draft, an
650	     * invoice already paid, or a date after today
651	     * or before the invoice's issue date is refused. The reference (null when none was quoted) has
652	     * already been checked; one that belongs to a different invoice is refused.
653	     */
654	    @Transactional
655	    public Optional<Invoice> recordPayment(Long invoiceId, BigDecimal amount, LocalDate date, String reference) {
656	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
657	        found.ifPresent(invoice -> {
658	            if (invoice.isDraft()) {
659	                throw new InvoiceRejectedException("Send the invoice before recording a payment.");
660	            }
661	            if (invoice.isVoid()) {
662	                throw new InvoiceRejectedException("A void invoice takes no payments.");
663	            }
664	            if (invoice.isCreditNote()) {
665	                throw new InvoiceRejectedException("A credit note takes no payments.");
666	            }
667	            BigDecimal paidSoFar = paid(List.of(invoice)).get(invoice.getId());
668	            BigDecimal due = invoice.amountDue(paidSoFar, taxRate.percent());
669	            if (due.signum() <= 0) {
670	                throw new InvoiceRejectedException("This invoice has already been paid.");
671	            }
672	            BigDecimal applied = amount.min(due);
673	            if (invoice.hasPlan() && invoice.isTooSmallPart(applied, paidSoFar, taxRate.percent())) {
674	                throw new InvoiceRejectedException("A payment must be at least the $"
675	                        + invoice.earliestUnpaid(paidSoFar, taxRate.percent()).toPlainString()
676	                        + " still unpaid on the earliest unpaid instalment, unless it settles the plan.");
677	            }
678	            if (invoice.isTooSmallPart(applied, paidSoFar, taxRate.percent())) {
679	                throw new InvoiceRejectedException("A part payment must be at least $"
680	                        + invoice.minimumPart(taxRate.percent()).toPlainString()
681	                        + " (10% of the total), unless it settles the invoice.");
682	            }
683	            LocalDate now = today.date();
684	            if (date.isAfter(now)) {
685	                throw new InvoiceRejectedException("The payment date cannot be after today (" + now + ").");
686	            }
687	            if (invoice.getIssueDate() != null && date.isBefore(invoice.getIssueDate())) {
688	                throw new InvoiceRejectedException(
689	                        "The payment date cannot be before the invoice's issue date (" + invoice.getIssueDate() + ").");
690	            }
691	            if (reference != null && !reference.equals(PaymentReference.of(invoice.getId()))) {
692	                throw new InvoiceRejectedException(PaymentReference.grouped(reference)
693	                        + " is the reference of a different invoice; this invoice's is "
694	                        + PaymentReference.grouped(PaymentReference.of(invoice.getId())) + ".");
695	            }
696	            Payment payment = payments.saveAndFlush(Payment.against(invoice, amount, applied, date, reference));
697	            audit.record("PAYMENT_RECORDED id=" + payment.getId() + " invoice=" + invoice.getId() + " amount="
698	                    + applied.setScale(2, RoundingMode.UNNECESSARY).toPlainString());
699	            recordWriteOff(invoice);
700	            recordCreditHeld(payment);
701	        });
702	        return found;
703	    }
704	
705	    /**
706	     * Records one payment of the amount on the date against the client's unpaid sent invoices, earliest
707	     * due date first (lower id first on the same due date) so overdue invoices are cleared first,
708	     * paying each off in full before the next.
709	     * What it pays beyond everything the client owes is held on the client's account as credit; the
710	     * rest is checked and recorded as a split payment over the invoices it reaches.
711	     * References (empty when none, each already checked) instead limit the payment to the client's
712	     * invoices with those references, applied in the same order; one that is not the reference of any
713	     * of the client's invoices is refused; what is paid beyond what those invoices owe together is held
714	     * as credit.
715	     * The payment keeps the reference of the first invoice it reaches.
716	     */
717	    @Transactional
718	    public Payment recordAutoPayment(Long clientId, BigDecimal amount, LocalDate date, List<String> references) {
719	        List<Invoice> ofClient = invoices.findByClientIdOrderByIdAsc(clientId);
720	        List<Invoice> candidates = ofClient;
721	        if (!references.isEmpty()) {
722	            Set<Long> named = new HashSet<>();
723	            for (String reference : references) {
724	                Invoice invoice = ofClient.stream()
725	                        .filter(i -> reference.equals(PaymentReference.of(i.getId())))
726	                        .findFirst()
727	                        .orElseThrow(() -> new InvoiceRejectedException(PaymentReference.grouped(reference)
728	                                + " is not the reference of any of this client's invoices."));
729	                String number = InvoiceNumber.of(invoice.getId());
730	                if (invoice.isDraft()) {
731	                    throw new InvoiceRejectedException("Send " + number + " before recording a payment against it.");
732	                }
733	                if (invoice.isVoid()) {
734	                    throw new InvoiceRejectedException(number + " is void and takes no payments.");
735	                }
736	                if (invoice.isCreditNote()) {
737	                    throw new InvoiceRejectedException(invoice.number() + " is a credit note and takes no payments.");
738	                }
739	                named.add(invoice.getId());
740	            }
741	            candidates = ofClient.stream().filter(i -> named.contains(i.getId())).toList();
742	        }
743	        List<Invoice> sent = candidates.stream()
744	                .filter(i -> !i.isDraft() && !i.isVoid() && !i.isCreditNote())
745	                .sorted(Comparator.comparing(Invoice::getDueDate, Comparator.nullsLast(Comparator.naturalOrder()))
746	                        .thenComparing(Invoice::getId))
747	                .toList();
748	        Map<Long, BigDecimal> paid = paid(sent);
749	        BigDecimal owed = BigDecimal.ZERO;
750	        BigDecimal left = amount;
751	        List<PaymentAllocation> parts = new ArrayList<>();
752	        for (Invoice invoice : sent) {
753	            BigDecimal due = invoice.amountDue(paid.get(invoice.getId()), taxRate.percent());
754	            if (due.signum() <= 0) {
755	                continue;
756	            }
757	            owed = owed.add(due);
758	            if (left.signum() > 0) {
759	                BigDecimal part = left.min(due);
760	                parts.add(new PaymentAllocation(invoice.getId(), part));
761	                left = left.subtract(part);
762	            }
763	        }
764	        if (owed.signum() <= 0) {
765	            throw new InvoiceRejectedException(references.isEmpty() ? "The client has no unpaid invoices to pay."
766	                    : "Those invoices have already been paid.");
767	        }
768	        String reference = references.isEmpty() ? null : PaymentReference.of(parts.get(0).getInvoiceId());
769	        return recordSpread(clientId, amount, date, reference, parts, true);
770	    }
771	
772	    /**
773	     * Records one payment of the amount on the date spread over several of the client's invoices, and
774	     * records each part in the audit. The amounts have already been checked to be more than zero; they
775	     * must add up exactly to the payment, and each must go to a different sent invoice of the client
776	     * and be no more than what it still has due. The date must be no later than today nor before any
777	     * of the invoices' issue dates. The reference (null when none) has already been checked; it must
778	     * be the reference of one of the invoices.
779	     */
780	    @Transactional
781	    public Payment recordSplitPayment(Long clientId, BigDecimal amount, LocalDate date, String reference,
782	            List<PaymentAllocation> parts) {
783	        return recordSpread(clientId, amount, date, reference, parts, false);
784	    }
785	
786	    /**
787	     * Records the payment spread over the parts as {@link #recordSplitPayment} does, except that when
788	     * credit may be held the parts may add up to less than the payment: the rest is held on the
789	     * client's account as credit and recorded in the audit.
790	     */
791	    private Payment recordSpread(Long clientId, BigDecimal amount, LocalDate date, String reference,
792	            List<PaymentAllocation> parts, boolean holdCredit) {
793	        if (parts.isEmpty()) {
794	            throw new InvoiceRejectedException("Enter how much of the payment goes to each invoice.");
795	        }
796	        BigDecimal sum = parts.stream().map(PaymentAllocation::getAmount).reduce(BigDecimal.ZERO, BigDecimal::add);
797	        if (holdCredit ? sum.compareTo(amount) > 0 : sum.compareTo(amount) != 0) {
798	            throw new InvoiceRejectedException("The amounts for the invoices add up to $"
799	                    + sum.setScale(2).toPlainString() + ", not the $" + amount.setScale(2).toPlainString() + " paid.");
800	        }
801	        LocalDate now = today.date();
802	        if (date.isAfter(now)) {
803	            throw new InvoiceRejectedException("The payment date cannot be after today (" + now + ").");
804	        }
805	        Set<Long> seen = new HashSet<>();
806	        List<Invoice> spreadOver = new ArrayList<>();
807	        for (PaymentAllocation part : parts) {
808	            if (!seen.add(part.getInvoiceId())) {
809	                throw new InvoiceRejectedException("Each invoice can take only one part of the payment.");
810	            }
811	            Invoice invoice = invoices.findWithLinesById(part.getInvoiceId())
812	                    .filter(i -> i.getClientId().equals(clientId))
813	                    .orElseThrow(() -> new InvoiceRejectedException("A part of the payment goes to an invoice of another client."));
814	            String number = InvoiceNumber.of(invoice.getId());
815	            if (invoice.isDraft()) {
816	                throw new InvoiceRejectedException("Send " + number + " before recording a payment against it.");
817	            }
818	            if (invoice.isVoid()) {
819	                throw new InvoiceRejectedException(number + " is void and takes no payments.");
820	            }
821	            if (invoice.isCreditNote()) {
822	                throw new InvoiceRejectedException(invoice.number() + " is a credit note and takes no payments.");
823	            }
824	            BigDecimal paidSoFar = paid(List.of(invoice)).get(invoice.getId());
825	            BigDecimal due = invoice.amountDue(paidSoFar, taxRate.percent());
826	            if (part.getAmount().compareTo(due) > 0) {
827	                throw new InvoiceRejectedException("The $" + part.getAmount().setScale(2).toPlainString() + " for "
828	                        + number + " is more than the $" + due.toPlainString() + " it has due.");
829	            }
830	            if (invoice.hasPlan() && invoice.isTooSmallPart(part.getAmount(), paidSoFar, taxRate.percent())) {
831	                throw new InvoiceRejectedException("The $" + part.getAmount().setScale(2).toPlainString() + " for "
832	                        + number + " is less than the $" + invoice.earliestUnpaid(paidSoFar, taxRate.percent()).toPlainString()
833	                        + " still unpaid on its earliest unpaid instalment, unless it settles the plan.");
834	            }
835	            if (invoice.isTooSmallPart(part.getAmount(), paidSoFar, taxRate.percent())) {
836	                throw new InvoiceRejectedException("The $" + part.getAmount().setScale(2).toPlainString() + " for "
837	                        + number + " is less than $" + invoice.minimumPart(taxRate.percent()).toPlainString()
838	                        + " (10% of its total), unless it settles the invoice.");
839	            }
840	            if (invoice.getIssueDate() != null && date.isBefore(invoice.getIssueDate())) {
841	                throw new InvoiceRejectedException("The payment date cannot be before the issue date of " + number
842	                        + " (" + invoice.getIssueDate() + ").");
843	            }
844	            spreadOver.add(invoice);
845	        }
846	        if (reference != null && spreadOver.stream().noneMatch(i -> reference.equals(PaymentReference.of(i.getId())))) {
847	            throw new InvoiceRejectedException(PaymentReference.grouped(reference)
848	                    + " is not the reference of any of the invoices being paid.");
849	        }
850	        Payment payment = payments.saveAndFlush(Payment.split(clientId, amount, date, reference, parts));
851	        for (PaymentAllocation part : parts) {
852	            audit.record("PAYMENT_RECORDED id=" + payment.getId() + " invoice=" + part.getInvoiceId() + " amount="
853	                    + part.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString());
854	        }
855	        spreadOver.forEach(this::recordWriteOff);
856	        recordCreditHeld(payment);
857	        return payment;
858	    }
859	
860	    /** Records in the audit what a payment just recorded holds on the client's account as credit, if anything. */
861	    private void recordCreditHeld(Payment payment) {
862	        BigDecimal credit = payment.credit();
863	        if (credit.signum() > 0) {
864	            audit.record("CREDIT_HELD payment=" + payment.getId() + " amount="
865	                    + credit.setScale(2, RoundingMode.UNNECESSARY).toPlainString());
866	        }
867	    }
868	
869	    /** Records in the audit what a payment just recorded left written off on the invoice, if anything. */
870	    private void recordWriteOff(Invoice invoice) {
871	        BigDecimal writtenOff = invoice.writtenOff(paid(List.of(invoice)).get(invoice.getId()), taxRate.percent());
872	        if (writtenOff.signum() > 0) {
873	            audit.record("INVOICE_WRITTEN_OFF id=" + invoice.getId() + " amount=" + writtenOff.toPlainString());
874	        }
875	    }
876	
877	    /**
878	     * Reverses the payment (a bounced cheque), undoing it on every invoice it was applied to, and
879	     * records it in the audit; empty if no such payment. A payment already reversed, or one that has
880	     * had any of its credit refunded, or credit from a credit note, is refused.
881	     */
882	    @Transactional
883	    public Optional<Payment> reversePayment(Long paymentId) {
884	        Optional<Payment> found = payments.findById(paymentId);
885	        found.ifPresent(payment -> {
886	            if (payment.isReversed()) {
887	                throw new InvoiceRejectedException("This payment has already been reversed.");
888	            }
889	            if (payment.getCreditNote() != null) {
890	                throw new InvoiceRejectedException("This is credit from a credit note, so it cannot be reversed.");
891	            }
892	            if (payment.getRefunded().signum() > 0) {
893	                throw new InvoiceRejectedException("This payment has had credit refunded, so it cannot be reversed.");
894	            }
895	            payment.reverse();
896	            payments.saveAndFlush(payment);
897	            audit.record("PAYMENT_REVERSED id=" + payment.getId() + " amount="
898	                    + payment.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString());
899	        });
900	        return found;
901	    }
902	}
