337	    /**
338	     * The balance of each client that has a sent invoice or credit; a client not listed owes nothing and
339	     * has no credit. Void invoices and credit notes do not count (a credit note comes off its original).
340	     */
341	    @GetMapping("/api/clients/balances")
342	    public List<ClientBalance> balances() {
343	        BigDecimal rate = taxRate.percent();
344	        List<Invoice> sent = invoices.all().stream().filter(i -> !i.isDraft() && !i.isVoid() && !i.isCreditNote()).toList();
345	        Map<Long, BigDecimal> paid = invoices.paid(sent);
346	        LocalDate on = today.date();
347	        Map<Long, BigDecimal[]> owed = new TreeMap<>();
348	        for (Invoice i : sent) {
349	            BigDecimal due = i.amountDue(paid.get(i.getId()), rate);
350	            BigDecimal[] sums = owed.computeIfAbsent(i.getClientId(),
351	                    k -> new BigDecimal[] { BigDecimal.ZERO.setScale(2), BigDecimal.ZERO.setScale(2) });
352	            sums[0] = sums[0].add(due).add(i.retentionHeld(rate));
353	            sums[1] = sums[1].add(i.overdueAmount(paid.get(i.getId()), rate, on));
354	        }
355	        Map<Long, BigDecimal> credits = invoices.credits();
356	        credits.keySet().forEach(clientId -> owed.computeIfAbsent(clientId,
357	                k -> new BigDecimal[] { BigDecimal.ZERO.setScale(2), BigDecimal.ZERO.setScale(2) }));
358	        return owed.entrySet().stream().map(e -> {
359	            BigDecimal credit = credits.getOrDefault(e.getKey(), BigDecimal.ZERO).setScale(2);
360	            return new ClientBalance(e.getKey(), e.getValue()[0].subtract(credit).toPlainString(),
361	                    e.getValue()[1].toPlainString(), credit.toPlainString());
362	        }).toList();
363	    }
