511	    private static String reference(String typed) {
512	        if (typed == null || typed.isBlank()) {
513	            return null;
514	        }
515	        Optional<String> parsed = typed.trim().toUpperCase().startsWith("INV")
516	                ? InvoiceNumber.idOf(typed).map(PaymentReference::of)
517	                : PaymentReference.parse(typed);
